mapper.select:
SELECT
  training_id, date, user_id, exercise_id, weight, reps, created_at, updated_at
FROM trainings
WHERE user_id = #{userId}
  AND updated_at > #{updatedAt}
ORDER BY training_id

SELECT user_id, COUNT(DISTINCT date) AS training_counts FROM trainings WHERE user_id IN
#{userId}
AND date BETWEEN #{startDate} AND #{endDate} GROUP BY user_id

SELECT t.user_id, u.nickname, t.date, b.parts_id, b.name body_parts_name FROM trainings t INNER JOIN exercises e ON t.exercise_id = CAST(e.exercise_id AS TEXT) INNER JOIN body_parts b ON e.parts_id = CAST(b.parts_id AS BIGINT) LEFT JOIN users u ON t.user_id = u.user_id WHERE t.user_id IN
#{userId}
GROUP BY t.user_id, u.nickname, t.date, b.parts_id, b.name ORDER BY t.date DESC, b.parts_id, MAX(t.created_at) DESC;

SELECT t.user_id, t.date, COUNT(DISTINCT t.exercise_id) AS exercise_count, SUM(t.weight * t.reps) AS total_volume, COUNT(*) AS total_sets, MAX(t.created_at) AS last_activity_at, p.weight AS profile_weight FROM trainings t INNER JOIN exercises e ON t.exercise_id = CAST(e.exercise_id AS TEXT) INNER JOIN body_parts b ON e.parts_id = CAST(b.parts_id AS BIGINT) LEFT JOIN users_profile p ON t.user_id = p.user_id WHERE t.user_id IN
#{userId}
GROUP BY t.user_id, t.date, p.weight
